-- #50 신고와 운영 처리 (ADR-0069 decision 2 #45-10…#45-15, decision 3 #37-10, decision 4 #50 rows,
-- decision 7; ADR-0081). Generated by `drizzle-kit generate`, then hand-edited where marked: this
-- header and the tail. The snapshot is as generated.
--
-- - report_reason: REPORT_REASONS (@buddha/shared), the eight reasons in the owner's order — a
--   report's, and the reason every moderation action carries (owner decision 2026-10-22, ADR-0080).
-- - reports: one row per report on a post, a comment or a profile, with the reporter's account and
--   the keyed hash of its verified number (decision 7), its intake and processing times (N05 §8).
-- - moderation_actions: one row per action an operator took on a member (hiding, warning, the
--   profile items), with its reason, operator, time and cancellation. `type` is a varchar held to
--   MODERATION_ACTION_TYPES by a CHECK, which #185 and #139 replace to add theirs.
-- - profile_item_removals: what a profile action took away, kept for operators (#37-10).
CREATE TYPE "public"."report_reason" AS ENUM('spam', 'harassment', 'personal_info', 'impersonation', 'collusion_manipulation', 'off_topic', 'rights_infringement', 'other');--> statement-breakpoint
CREATE TYPE "public"."report_status" AS ENUM('pending', 'actioned', 'dismissed');--> statement-breakpoint
CREATE TYPE "public"."report_target_type" AS ENUM('post', 'comment', 'profile');--> statement-breakpoint
CREATE TABLE "moderation_actions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"type" varchar(32) NOT NULL,
	"user_id" text NOT NULL,
	"post_id" uuid,
	"comment_id" uuid,
	"reason" "report_reason" NOT NULL,
	"note" varchar(500),
	"created_by" text NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"ends_at" timestamp (3) with time zone,
	"cancelled_at" timestamp (3) with time zone,
	"cancelled_by" text,
	"cancel_reason" varchar(500),
	CONSTRAINT "moderation_actions_type_check" CHECK ("moderation_actions"."type" IN ('hide', 'warning', 'nickname_reset', 'bio_clear', 'image_remove')),
	CONSTRAINT "moderation_actions_subject_check" CHECK (CASE "moderation_actions"."type" WHEN 'hide' THEN num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") = 1 WHEN 'warning' THEN num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") <= 1 ELSE num_nonnulls("moderation_actions"."post_id", "moderation_actions"."comment_id") = 0 END),
	CONSTRAINT "moderation_actions_note_check" CHECK ("moderation_actions"."note" IS NULL OR btrim("moderation_actions"."note") <> ''),
	CONSTRAINT "moderation_actions_other_note_check" CHECK ("moderation_actions"."reason" <> 'other' OR "moderation_actions"."note" IS NOT NULL),
	CONSTRAINT "moderation_actions_ends_at_check" CHECK ("moderation_actions"."ends_at" IS NULL),
	CONSTRAINT "moderation_actions_cancellation_check" CHECK (("moderation_actions"."cancelled_at" IS NULL) = ("moderation_actions"."cancelled_by" IS NULL) AND ("moderation_actions"."cancelled_at" IS NULL) = ("moderation_actions"."cancel_reason" IS NULL) AND btrim("moderation_actions"."cancel_reason") IS DISTINCT FROM ''),
	CONSTRAINT "moderation_actions_not_own_check" CHECK ("moderation_actions"."created_by" <> "moderation_actions"."user_id" AND "moderation_actions"."cancelled_by" IS DISTINCT FROM "moderation_actions"."user_id")
);
--> statement-breakpoint
CREATE TABLE "profile_item_removals" (
	"action_id" uuid PRIMARY KEY NOT NULL,
	"nickname" varchar(20),
	"bio" varchar(160),
	"image_id" uuid,
	CONSTRAINT "profile_item_removals_image_id_unique" UNIQUE("image_id"),
	CONSTRAINT "profile_item_removals_item_check" CHECK (num_nonnulls("profile_item_removals"."nickname", "profile_item_removals"."bio", "profile_item_removals"."image_id") = 1)
);
--> statement-breakpoint
CREATE TABLE "reports" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"target_type" "report_target_type" NOT NULL,
	"post_id" uuid,
	"comment_id" uuid,
	"reported_user_id" text NOT NULL,
	"target_key" text GENERATED ALWAYS AS (coalesce(post_id::text, comment_id::text, reported_user_id)) STORED NOT NULL,
	"reporter_id" text NOT NULL,
	"reporter_phone_hash" varchar(64) NOT NULL,
	"reason" "report_reason" NOT NULL,
	"description" varchar(500),
	"status" "report_status" DEFAULT 'pending' NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"resolved_at" timestamp (3) with time zone,
	"resolved_by" text,
	"action_id" uuid,
	"dismissal_reason" varchar(500),
	CONSTRAINT "reports_target_check" CHECK (("reports"."target_type" = 'post') = ("reports"."post_id" IS NOT NULL) AND ("reports"."target_type" = 'comment') = ("reports"."comment_id" IS NOT NULL)),
	CONSTRAINT "reports_phone_hash_check" CHECK ("reports"."reporter_phone_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "reports_description_check" CHECK ("reports"."description" IS NULL OR btrim("reports"."description") <> ''),
	CONSTRAINT "reports_other_description_check" CHECK ("reports"."reason" <> 'other' OR "reports"."description" IS NOT NULL),
	CONSTRAINT "reports_resolution_check" CHECK (("reports"."status" = 'pending') = ("reports"."resolved_at" IS NULL) AND ("reports"."resolved_at" IS NULL) = ("reports"."resolved_by" IS NULL) AND ("reports"."status" = 'actioned') = ("reports"."action_id" IS NOT NULL) AND ("reports"."status" = 'dismissed') = ("reports"."dismissal_reason" IS NOT NULL) AND btrim("reports"."dismissal_reason") IS DISTINCT FROM ''),
	CONSTRAINT "reports_not_own_check" CHECK ("reports"."reporter_id" <> "reports"."reported_user_id" AND "reports"."resolved_by" IS DISTINCT FROM "reports"."reported_user_id")
);
